create table public.profiles (id uuid primary key references auth.users on delete cascade, role text not null default 'student' check (role in ('student','admin')));
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id) values (new.id); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin'); $$;
create table public.lessons (id text primary key, category text not null check(category in ('BMC','BPC','Essay')), module text not null, title text not null, description text not null default '', pages integer not null check(pages between 1 and 1000), published boolean not null default false, pdf text not null);
create table public.progress (user_id uuid references auth.users on delete cascade, lesson_id text references public.lessons on delete cascade, page integer not null check(page>0), completed boolean not null default false, updated_at timestamptz not null default now(), primary key(user_id,lesson_id));
alter table public.profiles enable row level security;
alter table public.lessons enable row level security;
alter table public.progress enable row level security;
create policy profile_read on public.profiles for select to authenticated using(id=auth.uid());
create policy lesson_read on public.lessons for select to authenticated using(published or public.is_admin());
create policy lesson_admin on public.lessons for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy progress_read on public.progress for select to authenticated using(user_id=auth.uid());
create policy progress_insert on public.progress for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from public.lessons where id=lesson_id and published and page<=pages));
create policy progress_update on public.progress for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid() and exists(select 1 from public.lessons where id=lesson_id and published and page<=pages));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('materials','materials',false,20971520,array['application/pdf']);
create policy material_read on storage.objects for select to authenticated using(bucket_id='materials' and (public.is_admin() or exists(select 1 from public.lessons where pdf=name and published)));
create policy material_admin_insert on storage.objects for insert to authenticated with check(bucket_id='materials' and public.is_admin());
create policy material_admin_update on storage.objects for update to authenticated using(bucket_id='materials' and public.is_admin()) with check(bucket_id='materials' and public.is_admin());
create policy material_admin_delete on storage.objects for delete to authenticated using(bucket_id='materials' and public.is_admin());
